def magic_square_test(matrix):
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)
    target_sum = sum(matrix[0]) // n

    # Check rows
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != target_sum:
            return False

    # Check diagonals
    diag1 = sum(matrix[i][i] for i in range(n))
    diag2 = sum(matrix[i][n - 1 - i] for i in range(n))
    if diag1 != target_sum or diag2 != target_sum:
        return False

    # Check all numbers are unique and in range 1 to n^2
    seen = set()
    for row in matrix:
        for num in row:
            if not (1 <= num <= n * n) or num in seen:
                return False
            seen.add(num)

    return True
```

