def breakSum(n):
    if n == 0:
        return 0
    if n == 1:
        return 1

    max_sum = 0
    for i in range(1, n):
        for j in range(1, n - i):
            k = n - i - j
            if k > 0:
                current_sum = i + j + k + breakSum(i) + breakSum(j) + breakSum(k)
                max_sum = max(max_sum, current_sum)

    return max_sum
```

