        return False
    for i in range(int(n**0.5) + 1):
        if (n - i*i) % (i*i) == 0:
            # Check if the quotient is a perfect square
            quotient = (n - i*i) // (i*i)
            if quotient == 0:
                return True
            root = int(quotient**0.5)
            if root * root == quotient:
                return True
    return False
